<script setup lang="ts">
import { Link, router, usePage } from '@inertiajs/vue3'
import { ArrowLeft, Check, Eye, Layers, Plus } from '@lucide/vue'
interface Handover { id: number; number: string; type: string; status: string; transaction_date: string; sender: { id: number; name: string }; receiver: { name: string }; items: { item_type: { name: string; unit: string } | null; manual_name: string | null; quantity: number; condition: string }[] }
interface Pagination { data: Handover[] }
interface PageProps { [key: string]: unknown; flash?: { success?: string }; auth: { user: { id: number; role: string } | null } }
const props = defineProps<{ handovers: Pagination }>()
const page = usePage<PageProps>()
function confirmSender(id: number): void { router.post(route('handovers.confirm-sender', id)) }
</script>
<template>
  <div class="min-h-screen pb-8"><header class="sticky top-0 z-10 border-b bg-white/95 px-4 py-4 backdrop-blur"><div class="mx-auto flex max-w-3xl items-center justify-between"><div class="flex items-center gap-3"><Link :href="route('dashboard')" class="rounded-xl p-2 text-muted-foreground"><ArrowLeft class="size-5" /></Link><div><p class="text-xs uppercase tracking-wider text-primary">SERAYA</p><h1 class="text-xl font-bold">Serah Terima</h1></div></div><div class="flex items-center gap-2"><Link :href="route('handovers.batch.create')" class="flex size-10 items-center justify-center rounded-full border text-primary" title="Batch Serah Terima"><Layers class="size-5" /></Link><Link :href="route('handovers.create')" class="flex size-10 items-center justify-center rounded-full bg-primary text-primary-foreground"><Plus class="size-5" /></Link></div></div></header>
  <main class="mx-auto max-w-3xl space-y-4 px-4 py-6"><div v-if="page.props.flash?.success" class="rounded-2xl bg-green-50 p-4 text-sm font-medium text-green-700">{{ page.props.flash.success }}</div><div v-if="props.handovers.data.length" class="space-y-3"><article v-for="handover in props.handovers.data" :key="handover.id" class="rounded-2xl border bg-card p-4 shadow-sm"><div class="flex items-start justify-between gap-3"><div><p class="text-xs font-semibold text-primary">{{ handover.number }}</p><h2 class="mt-1 font-semibold">{{ handover.type }}</h2></div><span class="rounded-full bg-amber-100 px-2 py-1 text-xs font-medium text-amber-700">{{ handover.status }}</span></div><p class="mt-3 text-sm text-muted-foreground">{{ handover.sender.name }} → {{ handover.receiver.name }}</p><p class="mt-1 text-xs text-muted-foreground">{{ handover.transaction_date }}</p><div class="mt-3 flex flex-wrap items-center justify-between gap-2"><div class="flex flex-wrap gap-2"><span v-for="item in handover.items" :key="`${item.item_type?.name ?? item.manual_name}-${item.quantity}`" class="rounded-full bg-muted px-2 py-1 text-xs">{{ item.item_type?.name ?? item.manual_name }} × {{ item.quantity }}</span></div><div class="flex flex-wrap gap-2"><Link :href="route('handovers.show', handover.id)" class="flex items-center gap-2 rounded-xl border px-3 py-2 text-xs font-semibold text-primary"><Eye class="size-4" />Lihat Detail</Link><button v-if="page.props.auth.user?.id === handover.sender.id && handover.status === 'MENUNGGU_KONFIRMASI'" type="button" class="flex items-center gap-2 rounded-xl bg-primary px-3 py-2 text-xs font-semibold text-primary-foreground" @click="confirmSender(handover.id)"><Check class="size-4" />Konfirmasi</button><a :href="route('handovers.pdf', handover.id)" class="flex items-center gap-2 rounded-xl border px-3 py-2 text-xs font-semibold text-primary"><Eye class="size-4" />Lihat PDF</a></div></div></article></div><div v-else class="rounded-2xl border border-dashed p-8 text-center text-sm text-muted-foreground">Belum ada transaksi serah terima.</div></main></div>
</template>
